'use client';
import { useId } from 'react';
import {
  Autocomplete,
  AutocompleteContent,
  AutocompleteEmpty,
  AutocompleteInput,
  AutocompleteItem,
  AutocompleteList
} from '@gaudi/design-system/core/Select';
import { zodResolver } from '@hookform/resolvers/zod';
import { Controller, useForm } from 'react-hook-form';
import ToastProvider, { toast } from '@gaudi/design-system/core/Toast';
import { z } from 'zod';
import {
  AlertRoot as Alert,
  AlertDescriptionPrimitive as AlertDescription
} from '@gaudi/design-system/core/Banner';
import { default as Button } from '@gaudi/design-system/core/Button';
import {
  FieldRoot as Field,
  FieldDescriptionPrimitive as FieldDescription,
  FieldErrorPrimitive as FieldError,
  FieldGroup,
  FieldLabelPrimitive as FieldLabel,
  FieldSet
} from '@gaudi/design-system/core/Field';
import { RegistryIcon } from '@gaudi/design-system/icons/RegistryIcon';
const FormSchema = z.object({
  feature: z
    .string()
    .min(1, 'Please select an item.')
    .refine(
      (val) => items.some((item) => item.value === val),
      'Please select a valid item.'
    )
});
export function Pattern() {
  const toastId = useId();
  const form = useForm({
    resolver: zodResolver(FormSchema),
    defaultValues: { feature: '' },
    mode: 'onSubmit',
    reValidateMode: 'onSubmit'
  });
  function onSubmit(data) {
    toast.success('Form submitted', {
      toasterId: toastId,
      description: (
        <Alert variant='default'>
          <RegistryIcon lucide='CircleAlertIcon' />
          <AlertDescription>
            Your form has successfully submitted with feature: {data.feature}
          </AlertDescription>
        </Alert>
      )
    });
    form.reset();
  }
  return (
    <>
      <ToastProvider id={toastId} />
    <div className='w-full max-w-xs'>
      <form onSubmit={form.handleSubmit(onSubmit)}>
        <FieldGroup>
          <FieldSet>
            <FieldGroup>
              <Controller
                name='feature'
                control={form.control}
                render={({ field, fieldState }) => (
                  <Field data-invalid={fieldState.invalid || void 0}>
                    <FieldLabel htmlFor={`${toastId}-feature`}>
                      Select Feature
                    </FieldLabel>
                    <Autocomplete
                      items={items}
                      value={field.value}
                      onValueChange={(value) => {
                        field.onChange(value);
                      }}
                    >
                      <AutocompleteInput
                        id={`${toastId}-feature`}
                        placeholder='e.g. feature'
                        aria-invalid={!!form.formState.errors.feature}
                      />
                      <AutocompleteContent>
                        <AutocompleteEmpty>No items found.</AutocompleteEmpty>
                        <AutocompleteList>
                          {(item) => (
                            <AutocompleteItem key={item.id} value={item.value}>
                              {item.value}
                            </AutocompleteItem>
                          )}
                        </AutocompleteList>
                      </AutocompleteContent>
                    </Autocomplete>
                    <FieldDescription>
                      Search and select a component feature.
                    </FieldDescription>
                    {fieldState.error && (
                      <FieldError>{fieldState.error?.message}</FieldError>
                    )}
                  </Field>
                )}
              />
            </FieldGroup>
          </FieldSet>
          <Field orientation='horizontal'>
            <Button
              variant='outline'
              type='button'
              onClick={() => form.reset()}
              className='flex-1'
            >
              Cancel
            </Button>
            <Button type='submit' className='flex-1'>
              Submit
            </Button>
          </Field>
        </FieldGroup>
      </form>
    </div>
    </>
  );
}
const items = [
  { id: 't1', value: 'feature' },
  { id: 't2', value: 'fix' },
  { id: 't3', value: 'bug' },
  { id: 't4', value: 'docs' },
  { id: 't5', value: 'internal' },
  { id: 't6', value: 'mobile' },
  { id: 'c-accordion', value: 'component: accordion' },
  { id: 'c-alert-dialog', value: 'component: alert dialog' },
  { id: 'c-autocomplete', value: 'component: autocomplete' },
  { id: 'c-avatar', value: 'component: avatar' },
  { id: 'c-checkbox', value: 'component: checkbox' },
  { id: 'c-checkbox-group', value: 'component: checkbox group' },
  { id: 'c-collapsible', value: 'component: collapsible' },
  { id: 'c-combobox', value: 'component: combobox' },
  { id: 'c-context-menu', value: 'component: context menu' },
  { id: 'c-dialog', value: 'component: dialog' },
  { id: 'c-field', value: 'component: field' },
  { id: 'c-fieldset', value: 'component: fieldset' },
  { id: 'c-filterable-menu', value: 'component: filterable menu' },
  { id: 'c-form', value: 'component: form' },
  { id: 'c-input', value: 'component: input' },
  { id: 'c-menu', value: 'component: menu' },
  { id: 'c-menubar', value: 'component: menubar' },
  { id: 'c-meter', value: 'component: meter' },
  { id: 'c-navigation-menu', value: 'component: navigation menu' },
  { id: 'c-number-field', value: 'component: number field' },
  { id: 'c-popover', value: 'component: popover' },
  { id: 'c-preview-card', value: 'component: preview card' },
  { id: 'c-progress', value: 'component: progress' },
  { id: 'c-radio', value: 'component: radio' },
  { id: 'c-scroll-area', value: 'component: scroll area' },
  { id: 'c-select', value: 'component: select' },
  { id: 'c-separator', value: 'component: separator' },
  { id: 'c-slider', value: 'component: slider' },
  { id: 'c-switch', value: 'component: switch' },
  { id: 'c-tabs', value: 'component: tabs' },
  { id: 'c-toast', value: 'component: toast' },
  { id: 'c-toggle', value: 'component: toggle' },
  { id: 'c-toggle-group', value: 'component: toggle group' },
  { id: 'c-toolbar', value: 'component: toolbar' },
  { id: 'c-tooltip', value: 'component: tooltip' }
];
